349	/* ─── CAMERA ─────────────────────────────────────── */
350	async function startCamera(){
351	  showScreen('cameraScreen');
352	  const pvC = document.getElementById('xrayPreviewCanvas');
353	  const sect = pvC.parentElement;
354	  pvC.width  = sect.clientWidth  || 400;
355	  pvC.height = sect.clientHeight || 280;
356	  animatePv(pvC);
357	
358	  document.getElementById('videoEl').style.display='block';
359	  document.getElementById('noCam').style.display='none';
360	
361	  try {
362	    const stream = await navigator.mediaDevices.getUserMedia({
363	      video:{facingMode:'user',width:{ideal:1280},height:{ideal:720}},
364	      audio:false
365	    });
366	    videoStream = stream;
367	    const vid = document.getElementById('videoEl');
368	    vid.srcObject = stream;
369	  } catch(e){
370	    console.warn('camera err',e);
371	    document.getElementById('videoEl').style.display='none';
372	    document.getElementById('noCam').style.display='flex';
373	  }
374	}
