376	/* ─── PREVIEW ANIMATION ──────────────────────────── */
377	function animatePv(canvas){
378	  if(pvRafId){cancelAnimationFrame(pvRafId);pvRafId=null;}
379	  const ctx = canvas.getContext('2d');
380	  function loop(){
381	    drawXrayBase(ctx, canvas.width, canvas.height, null, pvFrame++);
382	    pvRafId = requestAnimationFrame(loop);
383	  }
384	  loop();
385	}
386	function stopPv(){
387	  if(pvRafId){cancelAnimationFrame(pvRafId);pvRafId=null;}
388	}
