390	/* ─── CAPTURE ─────────────────────────────────────── */
391	function capture(){
392	  stopPv();
393	  playShutter();
394	  doFlash();
395	  currentMood = MOODS[Math.floor(Math.random()*MOODS.length)];
396	
397	  // Grab face frame
398	  const vid = document.getElementById('videoEl');
399	  const fc = document.createElement('canvas');
400	  fc.width  = vid.videoWidth  || 640;
401	  fc.height = vid.videoHeight || 480;
402	  const fx = fc.getContext('2d');
403	  fx.save(); fx.scale(-1,1); fx.translate(-fc.width,0);
404	  try{ fx.drawImage(vid,0,0,fc.width,fc.height); }catch(e){}
405	  fx.restore();
406	  faceDataURL = fc.toDataURL('image/jpeg',0.9);
407	
408	  if(videoStream) videoStream.getTracks().forEach(t=>t.stop());
409	
410	  setTimeout(buildResult, 350);
411	}
