441	    ctx.fillRect(0,faceH,W,divH);
442	    const dg = ctx.createLinearGradient(0,0,W,0);
443	    dg.addColorStop(0,'transparent'); dg.addColorStop(.5,'#00D4FF'); dg.addColorStop(1,'transparent');
444	    ctx.fillStyle=dg;
445	    ctx.fillRect(0,faceH+divH/2-1,W,2);
446	    ctx.fillStyle='#00D4FF';
447	    ctx.font='bold 13px Nanum Gothic,sans-serif';
448	    ctx.textAlign='center';
449	    ctx.textBaseline='middle';
450	    ctx.fillText('🩻 마음 X레이', W/2, faceH+divH/2);
