483	/* ─── SHUTTER SOUND ──────────────────────────────── */
484	function playShutter(){
485	  try{
486	    const AC = window.AudioContext||window.webkitAudioContext;
487	    if(!AC) return;
488	    const ac = new AC();
489	    const sr = ac.sampleRate;
490	    // Click burst
491	    const buf = ac.createBuffer(1,Math.floor(sr*.12),sr);
492	    const d = buf.getChannelData(0);
493	    for(let i=0;i<d.length;i++){
494	      d[i] = (Math.random()*2-1)*Math.exp(-i/(sr*.015));
495	    }
496	    const src = ac.createBufferSource(); src.buffer=buf;
497	    const hp = ac.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=1500;
498	    const g = ac.createGain(); g.gain.setValueAtTime(.85,ac.currentTime);
499	    g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.12);
500	    src.connect(hp); hp.connect(g); g.connect(ac.destination);
501	    src.start();
502	    // Thud
503	    setTimeout(()=>{
504	      try{
505	        const ac2=new AC();
506	        const o=ac2.createOscillator();
507	        const g2=ac2.createGain();
508	        o.frequency.setValueAtTime(180,ac2.currentTime);
509	        o.frequency.exponentialRampToValueAtTime(30,ac2.currentTime+.07);
510	        g2.gain.setValueAtTime(.7,ac2.currentTime);
511	        g2.gain.exponentialRampToValueAtTime(.001,ac2.currentTime+.08);
512	        o.connect(g2); g2.connect(ac2.destination);
513	        o.start(); o.stop(ac2.currentTime+.08);
514	      }catch(e){}
515	    },35);
516	  }catch(e){}
517	}
