526	/* ═══════════════════════════════════════════════════
527	   X-RAY DRAWING
528	═══════════════════════════════════════════════════ */
529	function drawXrayBase(ctx, W, H, mood, frame){
530	  // Background
531	  ctx.fillStyle='#030A18';
532	  ctx.fillRect(0,0,W,H);
533	
534	  // Scanlines
535	  for(let y=0;y<H;y+=3){
536	    ctx.fillStyle='rgba(0,50,120,.014)';
537	    ctx.fillRect(0,y,W,1);
538	  }
539	
540	  // Center glow
541	  const cGlow = ctx.createRadialGradient(W/2,H*.38,0,W/2,H*.38,W*.5);
542	  const gc = mood ? mood.glowColor : 'rgba(0,100,180,0.1)';
543	  cGlow.addColorStop(0,gc.replace(/[\d.]+\)$/,'0.1)'));
544	  cGlow.addColorStop(1,'transparent');
545	  ctx.fillStyle=cGlow; ctx.fillRect(0,0,W,H);
546	
547	  const cx=W/2;
548	
549	  // ── SPINE vertebrae
550	  for(let i=0;i<11;i++){
551	    const sy=H*.09+i*H*.062;
552	    const sw=W*.026+i*W*.0008;
553	    ctx.fillStyle=`rgba(150,200,255,${Math.min(.3+i*.015,.5)})`;
554	    ctx.strokeStyle=`rgba(190,225,255,${Math.min(.35+i*.015,.55)})`;
555	    ctx.lineWidth=.8;
556	    ctx.beginPath();
557	    if(ctx.roundRect) ctx.roundRect(cx-sw,sy-H*.018,sw*2,H*.034,3);
558	    else ctx.rect(cx-sw,sy-H*.018,sw*2,H*.034);
559	    ctx.fill(); ctx.stroke();
560	  }
561	
562	  // ── CLAVICLES
563	  ctx.save();
564	  ctx.strokeStyle='rgba(175,215,255,.72)';
565	  ctx.lineWidth=Math.max(W*.010,2);
566	  ctx.lineCap='round';
567	  ctx.beginPath();
568	  ctx.moveTo(cx-W*.04,H*.10);
569	  ctx.bezierCurveTo(cx-W*.12,H*.08,cx-W*.22,H*.10,cx-W*.30,H*.155);
570	  ctx.stroke();
571	  ctx.beginPath();
572	  ctx.moveTo(cx+W*.04,H*.10);
573	  ctx.bezierCurveTo(cx+W*.12,H*.08,cx+W*.22,H*.10,cx+W*.30,H*.155);
574	  ctx.stroke();
575	  ctx.restore();
576	
577	  // ── RIBS
578	  const ribs=[
579	    {y:.17,xf:.26,c:-.018},{y:.24,xf:.29,c:-.008},{y:.31,xf:.31,c:.000},
580	    {y:.38,xf:.30,c:.012},{y:.45,xf:.27,c:.024},{y:.51,xf:.23,c:.034},
581	  ];
582	  ctx.save();
583	  ctx.lineWidth=Math.max(W*.008,1.5);
584	  ctx.lineCap='round';
585	  ribs.forEach((r,i)=>{
586	    const ry=H*r.y;
587	    const al=(.55-i*.04);
588	    ctx.strokeStyle=`rgba(155,205,255,${al})`;
589	    ctx.beginPath();
590	    ctx.moveTo(cx-W*.035,ry);
591	    ctx.bezierCurveTo(cx-W*.11,ry+H*r.c,cx-W*(r.xf-.04),ry+H*(r.c+.025),cx-W*r.xf,ry+H*(r.c+.05));
592	    ctx.stroke();
593	    ctx.beginPath();
594	    ctx.moveTo(cx+W*.035,ry);
595	    ctx.bezierCurveTo(cx+W*.11,ry+H*r.c,cx+W*(r.xf-.04),ry+H*(r.c+.025),cx+W*r.xf,ry+H*(r.c+.05));
596	    ctx.stroke();
597	  });
598	  ctx.restore();
599	
600	  // ── LUNG OUTLINES
601	  ctx.save();
602	  ctx.strokeStyle='rgba(90,150,210,.20)';
603	  ctx.lineWidth=Math.max(W*.007,1.5);
604	  ctx.beginPath();
605	  ctx.ellipse(cx-W*.125,H*.34,W*.108,H*.195,-.06,0,Math.PI*2);
606	  ctx.stroke();
607	  ctx.beginPath();
608	  ctx.ellipse(cx+W*.125,H*.34,W*.108,H*.195,.06,0,Math.PI*2);
609	  ctx.stroke();
610	  ctx.restore();
611	
612	  // ── HEART
613	  const hx=cx-W*.04, hy=H*.31, hr=W*.095;
614	
615	  if(mood){
616	    // glow aura
617	    const hg=ctx.createRadialGradient(hx,hy,0,hx,hy,hr*2.6);
618	    hg.addColorStop(0,mood.glowColor);
619	    hg.addColorStop(1,'transparent');
620	    ctx.fillStyle=hg;
621	    ctx.beginPath(); ctx.arc(hx,hy,hr*2.6,0,Math.PI*2); ctx.fill();
622	    // heart shape
623	    drawHeart(ctx,hx,hy,hr,mood.heartColor,1.0);
624	    // mood decoration
625	    mood.draw(ctx,hx,hy,hr,W,H,frame);
626	  } else {
627	    // preview: pulsing outline
628	    const pulse=.85+.15*Math.sin(frame*.08);
629	    drawHeart(ctx,hx,hy,hr*pulse,'rgba(0,212,255,.5)',.5);
630	    ctx.font=`bold ${Math.round(hr*1.0)}px sans-serif`;
631	    ctx.textAlign='center'; ctx.textBaseline='middle';
632	    ctx.fillStyle=`rgba(0,212,255,${.3+.3*Math.sin(frame*.1)})`;
633	    ctx.fillText('?',hx,hy+hr*.1);
634	  }
635	
636	  // ── Watermark
637	  ctx.save();
638	  ctx.font=`${Math.round(W*.025)}px Nanum Gothic,sans-serif`;
639	  ctx.textAlign='left'; ctx.textBaseline='bottom';
640	  ctx.fillStyle='rgba(0,212,255,.25)';
641	  ctx.fillText('💝 마음 X레이 병원', W*.03, H*.97);
642	  ctx.restore();
643	}
