645	/* Heart shape helper */
646	function drawHeart(ctx,x,y,r,color,alpha){
647	  ctx.save();
648	  ctx.globalAlpha=alpha;
649	  ctx.fillStyle=color;
650	  ctx.beginPath();
651	  ctx.moveTo(x, y+r*.3);
652	  ctx.bezierCurveTo(x,   y-r*.3, x-r*1.1, y-r*.3, x-r*1.1, y+r*.25);
653	  ctx.bezierCurveTo(x-r*1.1, y+r*.75, x, y+r*1.2, x, y+r*1.35);
654	  ctx.bezierCurveTo(x, y+r*1.2, x+r*1.1, y+r*.75, x+r*1.1, y+r*.25);
655	  ctx.bezierCurveTo(x+r*1.1, y-r*.3, x, y-r*.3, x, y+r*.3);
656	  ctx.fill();
657	  ctx.restore();
658	}
