    [G5,1],[G5,1],[F5,1],[F5,1],
    [E5,1],[E5,1],[D5,2],
    [G5,1],[G5,1],[F5,1],[F5,1],
    [E5,1],[E5,1],[D5,2],
    // 다시 반짝반짝
    [C5,1],[C5,1],[G5,1],[G5,1],
    [A5,1],[A5,1],[G5,2],
    [F5,1],[F5,1],[E5,1],[E5,1],
    [D5,1],[D5,1],[C5,2],
  ];

