function playShutter(){
  try{
    // BGM AudioContext를 함께 쓰거나 새로 생성
    const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return;
    const ac=BGM.getAC()||new AC();
    if(ac.state==='suspended') ac.resume();
    const t=ac.currentTime;

    /* ── 노이즈 버스트 생성 helper ── */
    function noiseBurst(startT, dur, hpFreq, lpFreq, vol){
      const len=Math.ceil(ac.sampleRate*dur);
      const buf=ac.createBuffer(1,len,ac.sampleRate);
      const d=buf.getChannelData(0);
      for(let i=0;i<len;i++) d[i]=(Math.random()*2-1);
      const src=ac.createBufferSource(); src.buffer=buf;
      const hp=ac.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=hpFreq;
      const lp=ac.createBiquadFilter(); lp.type='lowpass';  lp.frequency.value=lpFreq;
      const g=ac.createGain();
      g.gain.setValueAtTime(vol,startT);
      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
      src.connect(hp); hp.connect(lp); lp.connect(g); g.connect(ac.destination);
      src.start(startT);
    }

    function oscThud(startT, f1, f2, dur, vol){
      const osc=ac.createOscillator();
      const g=ac.createGain();
      osc.frequency.setValueAtTime(f1,startT);
      osc.frequency.exponentialRampToValueAtTime(f2,startT+dur);
      g.gain.setValueAtTime(vol,startT);
      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
      osc.connect(g); g.connect(ac.destination);
      osc.start(startT); osc.stop(startT+dur+0.01);
    }

    // ① 찰— : 미러 올라가는 소리 (저음 쿵 + 중고음 클릭)
    oscThud(t,      220, 35,  0.045, 0.55);   // 쿵
    noiseBurst(t,   0.006, 1800, 8000, 0.80); // 딱

    // ② —칵 : 셔터 블레이드 열림 (날카로운 클릭)
    noiseBurst(t+0.020, 0.004, 3500, 12000, 0.65); // 칵!

    // ③ 셔터 블레이드 닫힘
    noiseBurst(t+0.038, 0.003, 3000, 10000, 0.45);

    // ④ 미러 복귀 (약간 낮고 부드러운 쿵)
    oscThud(t+0.058, 160, 28, 0.040, 0.30);
    noiseBurst(t+0.058, 0.007, 800, 4000, 0.28);

    // ⑤ 금속 울림 (살짝 남는 공명)
    const res=ac.createOscillator();
    const rg=ac.createGain();
    res.type='sine'; res.frequency.value=3200;
    rg.gain.setValueAtTime(0.04,t+0.01);
    rg.gain.exponentialRampToValueAtTime(0.001,t+0.14);
    res.connect(rg); rg.connect(ac.destination);
    res.start(t+0.01); res.stop(t+0.15);

  }catch(e){ console.log('shutter audio err',e); }
}

