346	   🎵 BGM ENGINE  (Web Audio API — no external files)
347	═══════════════════════════════════════════════════ */
348	const BGM = (() => {
349	  /* ── 음표 주파수 계산 ── */
350	  function hz(name, oct){
351	    const s={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
352	    return 440*Math.pow(2,(s[name]+(oct-4)*12-9)/12);
353	  }
354	  const C3=hz('C',3),G3=hz('G',3),F3=hz('F',3),A3=hz('A',3),E3=hz('E',3);
355	  const C4=hz('C',4),D4=hz('D',4),E4=hz('E',4),F4=hz('F',4),G4=hz('G',4),A4=hz('A',4);
356	  const C5=hz('C',5),D5=hz('D',5),E5=hz('E',5),F5=hz('F',5),G5=hz('G',5),A5=hz('A',5);
357	  const C6=hz('C',6);
358	
359	  const BPM  = 126;
360	  const BEAT = 60/BPM; // ≈0.476 s
361	
362	  /* ── 멜로디: [주파수, 박자]  (0 = 쉼표) ── */
363	  // 원작 귀여운 동요풍 멜로디 (반짝반짝 작은별 변형 + 마무리)
364	  const MEL = [
365	    // 반짝반짝 작은별
366	    [C5,1],[C5,1],[G5,1],[G5,1],
367	    [A5,1],[A5,1],[G5,2],
368	    [F5,1],[F5,1],[E5,1],[E5,1],
369	    [D5,1],[D5,1],[C5,2],
370	    // 높은 하늘 위에서
371	    [G5,1],[G5,1],[F5,1],[F5,1],
372	    [E5,1],[E5,1],[D5,2],
373	    [G5,1],[G5,1],[F5,1],[F5,1],
374	    [E5,1],[E5,1],[D5,2],
375	    // 다시 반짝반짝
376	    [C5,1],[C5,1],[G5,1],[G5,1],
377	    [A5,1],[A5,1],[G5,2],
378	    [F5,1],[F5,1],[E5,1],[E5,1],
379	    [D5,1],[D5,1],[C5,2],
380	  ];
381	
382	  /* ── 베이스: [주파수, 박자] ── */
383	  const BASS = [
384	    [C3,4],[G3,4],[F3,4],[C3,4],
385	    [G3,4],[F3,4],[G3,4],[G3,4],
386	    [C3,4],[G3,4],[F3,4],[C3,4],
387	    [G3,4],[F3,4],[G3,4],[C3,4],
388	    [C3,4],[G3,4],[F3,4],[C3,4],
389	    [G3,4],[F3,4],[G3,4],[G3,4],
390	    [C3,4],[G3,4],[F3,4],[C3,4],
391	    [F3,4],[G3,4],[C3,4],[C3,4],
392	  ];
393	
394	  /* ── 화음 (두 번째 보이스, 3도 아래) ── */
395	  const HARM = [
396	    [E4,1],[E4,1],[B4,1],[B4,1],
397	    [C5,1],[C5,1],[B4,2],
398	    [A4,1],[A4,1],[G4,1],[G4,1],
399	    [F4,1],[F4,1],[E4,2],
400	    [B4,1],[B4,1],[A4,1],[A4,1],
401	    [G4,1],[G4,1],[F4,2],
402	    [B4,1],[B4,1],[A4,1],[A4,1],
403	    [G4,1],[G4,1],[F4,2],
404	    [E4,1],[E4,1],[B4,1],[B4,1],
405	    [C5,1],[C5,1],[B4,2],
406	    [A4,1],[A4,1],[G4,1],[G4,1],
407	    [F4,1],[F4,1],[E4,2],
408	  ];
409	
410	  let ac=null, masterGain=null, playing=false, loopTimer=null;
411	
412	  function getAC(){
413	    if(!ac){
414	      const AC=window.AudioContext||window.webkitAudioContext;
415	      if(!AC) return null;
416	      ac=new AC();
417	      masterGain=ac.createGain();
418	      masterGain.gain.value=0;
419	      masterGain.connect(ac.destination);
420	    }
421	    return ac;
422	  }
423	
424	  function note(freq, t, dur, type, vol){
425	    if(!freq||!ac) return;
426	    const osc=ac.createOscillator();
427	    const g=ac.createGain();
428	    const atk=Math.min(0.02,dur*.12);
429	    const rel=Math.min(0.06,dur*.18);
430	    osc.type=type; osc.frequency.value=freq;
431	    g.gain.setValueAtTime(0,t);
432	    g.gain.linearRampToValueAtTime(vol,t+atk);
433	    g.gain.setValueAtTime(vol,t+dur-rel);
434	    g.gain.linearRampToValueAtTime(0,t+dur);
435	    osc.connect(g); g.connect(masterGain);
436	    osc.start(t); osc.stop(t+dur+0.06);
437	  }
438	
439	  function scheduleLoop(startT){
440	    if(!playing) return;
441	    let mt=startT, bt=startT, ht=startT;
442	    let totalBeats=0;
443	
444	    MEL.forEach(([f,b])=>{
445	      note(f, mt, b*BEAT*.86, 'sine', 0.20);
446	      mt+=b*BEAT; totalBeats+=b;
447	    });
448	    BASS.forEach(([f,b])=>{
449	      note(f, bt, b*BEAT*.70, 'triangle', 0.09);
450	      bt+=b*BEAT;
451	    });
452	    HARM.forEach(([f,b])=>{
453	      note(f, ht, b*BEAT*.82, 'sine', 0.07);
454	      ht+=b*BEAT;
455	    });
456	
457	    const loopSec=totalBeats*BEAT;
458	    loopTimer=setTimeout(()=>{ if(playing) scheduleLoop(startT+loopSec); },
459	      (loopSec-0.5)*1000);
460	  }
461	
462	  return {
463	    start(){
464	      const a=getAC(); if(!a) return;
465	      if(a.state==='suspended') a.resume();
466	      if(playing) return;
467	      playing=true;
468	      // 페이드인
469	      masterGain.gain.cancelScheduledValues(a.currentTime);
470	      masterGain.gain.setValueAtTime(0,a.currentTime);
471	      masterGain.gain.linearRampToValueAtTime(0.38,a.currentTime+1.8);
472	      scheduleLoop(a.currentTime+0.25);
473	    },
474	    stop(){
475	      playing=false;
476	      if(loopTimer){clearTimeout(loopTimer);loopTimer=null;}
477	      if(ac&&masterGain){
478	        masterGain.gain.cancelScheduledValues(ac.currentTime);
479	        masterGain.gain.setTargetAtTime(0,ac.currentTime,0.35);
480	      }
481	    },
482	    toggle(){
483	      if(playing){this.stop();return false;}
484	      else{this.start();return true;}
485	    },
486	    isPlaying(){return playing;},
487	    getAC(){return getAC();}
488	  };
489	})();
