501	/* ═══════════════════════════════════════════════════
502	   📸 찰칵! 셔터 효과음  (실제 DSLR 카메라 재현)
503	═══════════════════════════════════════════════════ */
504	function playShutter(){
505	  try{
506	    // BGM AudioContext를 함께 쓰거나 새로 생성
507	    const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return;
508	    const ac=BGM.getAC()||new AC();
509	    if(ac.state==='suspended') ac.resume();
510	    const t=ac.currentTime;
511	
512	    /* ── 노이즈 버스트 생성 helper ── */
513	    function noiseBurst(startT, dur, hpFreq, lpFreq, vol){
514	      const len=Math.ceil(ac.sampleRate*dur);
515	      const buf=ac.createBuffer(1,len,ac.sampleRate);
516	      const d=buf.getChannelData(0);
517	      for(let i=0;i<len;i++) d[i]=(Math.random()*2-1);
518	      const src=ac.createBufferSource(); src.buffer=buf;
519	      const hp=ac.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=hpFreq;
520	      const lp=ac.createBiquadFilter(); lp.type='lowpass';  lp.frequency.value=lpFreq;
521	      const g=ac.createGain();
522	      g.gain.setValueAtTime(vol,startT);
523	      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
524	      src.connect(hp); hp.connect(lp); lp.connect(g); g.connect(ac.destination);
525	      src.start(startT);
526	    }
527	
528	    function oscThud(startT, f1, f2, dur, vol){
529	      const osc=ac.createOscillator();
530	      const g=ac.createGain();
531	      osc.frequency.setValueAtTime(f1,startT);
532	      osc.frequency.exponentialRampToValueAtTime(f2,startT+dur);
533	      g.gain.setValueAtTime(vol,startT);
534	      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
535	      osc.connect(g); g.connect(ac.destination);
536	      osc.start(startT); osc.stop(startT+dur+0.01);
537	    }
538	
539	    // ① 찰— : 미러 올라가는 소리 (저음 쿵 + 중고음 클릭)
540	    oscThud(t,      220, 35,  0.045, 0.55);   // 쿵
541	    noiseBurst(t,   0.006, 1800, 8000, 0.80); // 딱
542	
543	    // ② —칵 : 셔터 블레이드 열림 (날카로운 클릭)
544	    noiseBurst(t+0.020, 0.004, 3500, 12000, 0.65); // 칵!
545	
546	    // ③ 셔터 블레이드 닫힘
547	    noiseBurst(t+0.038, 0.003, 3000, 10000, 0.45);
548	
549	    // ④ 미러 복귀 (약간 낮고 부드러운 쿵)
550	    oscThud(t+0.058, 160, 28, 0.040, 0.30);
551	    noiseBurst(t+0.058, 0.007, 800, 4000, 0.28);
552	
553	    // ⑤ 금속 울림 (살짝 남는 공명)
554	    const res=ac.createOscillator();
555	    const rg=ac.createGain();
556	    res.type='sine'; res.frequency.value=3200;
557	    rg.gain.setValueAtTime(0.04,t+0.01);
558	    rg.gain.exponentialRampToValueAtTime(0.001,t+0.14);
559	    res.connect(rg); rg.connect(ac.destination);
560	    res.start(t+0.01); res.stop(t+0.15);
561	
562	  }catch(e){ console.log('shutter audio err',e); }
563	}
