695	/* ─── BUILD RESULT ───────────────────────────────── */
696	function buildResult(){
697	  showScreen('resultScreen');
698	  const mood = currentMood;
699	  const RC = document.getElementById('resultCanvas');
700	  const W=460, H=680;
701	  RC.width=W; RC.height=H;
702	  const ctx = RC.getContext('2d');
703	
704	  const faceH = Math.round(H*0.40);
705	  const divH  = 28;
706	  const xrayY = faceH + divH;
707	  const xrayH = H - xrayY;
708	
709	  // 1. Face photo
710	  const img = new Image();
711	  img.onload = ()=>{
712	    ctx.save();
713	    ctx.beginPath();
714	    ctx.rect(0,0,W,faceH);
715	    ctx.clip();
716	    const sc = Math.max(W/img.naturalWidth, faceH/img.naturalHeight);
717	    const sw = img.naturalWidth*sc, sh = img.naturalHeight*sc;
718	    ctx.drawImage(img,(W-sw)/2,(faceH-sh)/2,sw,sh);
719	    ctx.restore();
720	
721	    // 2. Divider bar
722	    ctx.fillStyle='#08101E';
723	    ctx.fillRect(0,faceH,W,divH);
724	    const dg = ctx.createLinearGradient(0,0,W,0);
725	    dg.addColorStop(0,'transparent'); dg.addColorStop(.5,'#00D4FF'); dg.addColorStop(1,'transparent');
726	    ctx.fillStyle=dg;
727	    ctx.fillRect(0,faceH+divH/2-1,W,2);
728	    ctx.fillStyle='#00D4FF';
729	    ctx.font='bold 13px Nanum Gothic,sans-serif';
730	    ctx.textAlign='center';
731	    ctx.textBaseline='middle';
732	    ctx.fillText('🩻 마음 X레이', W/2, faceH+divH/2);
733	
734	    // 3. X-ray lower half
735	    ctx.save();
736	    ctx.translate(0, xrayY);
737	    drawXrayBase(ctx, W, xrayH, mood, 0);
738	    ctx.restore();
739	
740	    // 4. Mood label strip at bottom
741	    const lh = 52;
742	    ctx.fillStyle='rgba(0,0,0,.6)';
743	    ctx.fillRect(0, H-lh, W, lh);
744	    ctx.font=`bold ${Math.round(W*0.065)}px Nanum Gothic,sans-serif`;
745	    ctx.fillStyle=mood.heartColor;
746	    ctx.shadowColor=mood.heartColor; ctx.shadowBlur=10;
747	    ctx.textAlign='center'; ctx.textBaseline='middle';
748	    ctx.fillText(mood.emoji+' '+mood.name, W/2, H-lh/2);
749	    ctx.shadowBlur=0;
750	  };
751	  img.src = faceDataURL || '';
752	
753	  // 결과 팡파르 🎉
754	  setTimeout(playResultJingle, 200);
755	
756	  document.getElementById('moodEmoji').textContent = mood.emoji;
757	  document.getElementById('moodName').textContent  = mood.name;
758	  document.getElementById('moodDesc').textContent  = mood.desc;
759	  document.getElementById('prescTxt').textContent  = mood.prescription;
760	}
