777	/* ═══════════════════════════════════════════════════
778	   X-RAY DRAWING
779	═══════════════════════════════════════════════════ */
780	function drawXrayBase(ctx, W, H, mood, frame){
781	  // Background
782	  ctx.fillStyle='#030A18';
783	  ctx.fillRect(0,0,W,H);
784	
785	  // Scanlines
786	  for(let y=0;y<H;y+=3){
787	    ctx.fillStyle='rgba(0,50,120,.014)';
788	    ctx.fillRect(0,y,W,1);
789	  }
790	
791	  // Center glow
792	  const cGlow = ctx.createRadialGradient(W/2,H*.38,0,W/2,H*.38,W*.5);
793	  const gc = mood ? mood.glowColor : 'rgba(0,100,180,0.1)';
794	  cGlow.addColorStop(0,gc.replace(/[\d.]+\)$/,'0.1)'));
795	  cGlow.addColorStop(1,'transparent');
796	  ctx.fillStyle=cGlow; ctx.fillRect(0,0,W,H);
797	
798	  const cx=W/2;
799	
800	  // ── SPINE vertebrae
801	  for(let i=0;i<11;i++){
802	    const sy=H*.09+i*H*.062;
803	    const sw=W*.026+i*W*.0008;
804	    ctx.fillStyle=`rgba(150,200,255,${Math.min(.3+i*.015,.5)})`;
805	    ctx.strokeStyle=`rgba(190,225,255,${Math.min(.35+i*.015,.55)})`;
806	    ctx.lineWidth=.8;
807	    ctx.beginPath();
808	    if(ctx.roundRect) ctx.roundRect(cx-sw,sy-H*.018,sw*2,H*.034,3);
809	    else ctx.rect(cx-sw,sy-H*.018,sw*2,H*.034);
810	    ctx.fill(); ctx.stroke();
811	  }
812	
813	  // ── CLAVICLES
814	  ctx.save();
815	  ctx.strokeStyle='rgba(175,215,255,.72)';
816	  ctx.lineWidth=Math.max(W*.010,2);
817	  ctx.lineCap='round';
818	  ctx.beginPath();
819	  ctx.moveTo(cx-W*.04,H*.10);
820	  ctx.bezierCurveTo(cx-W*.12,H*.08,cx-W*.22,H*.10,cx-W*.30,H*.155);
821	  ctx.stroke();
822	  ctx.beginPath();
823	  ctx.moveTo(cx+W*.04,H*.10);
824	  ctx.bezierCurveTo(cx+W*.12,H*.08,cx+W*.22,H*.10,cx+W*.30,H*.155);
825	  ctx.stroke();
826	  ctx.restore();
827	
828	  // ── RIBS
829	  const ribs=[
830	    {y:.17,xf:.26,c:-.018},{y:.24,xf:.29,c:-.008},{y:.31,xf:.31,c:.000},
831	    {y:.38,xf:.30,c:.012},{y:.45,xf:.27,c:.024},{y:.51,xf:.23,c:.034},
832	  ];
833	  ctx.save();
834	  ctx.lineWidth=Math.max(W*.008,1.5);
835	  ctx.lineCap='round';
836	  ribs.forEach((r,i)=>{
837	    const ry=H*r.y;
838	    const al=(.55-i*.04);
839	    ctx.strokeStyle=`rgba(155,205,255,${al})`;
840	    ctx.beginPath();
841	    ctx.moveTo(cx-W*.035,ry);
842	    ctx.bezierCurveTo(cx-W*.11,ry+H*r.c,cx-W*(r.xf-.04),ry+H*(r.c+.025),cx-W*r.xf,ry+H*(r.c+.05));
843	    ctx.stroke();
844	    ctx.beginPath();
845	    ctx.moveTo(cx+W*.035,ry);
846	    ctx.bezierCurveTo(cx+W*.11,ry+H*r.c,cx+W*(r.xf-.04),ry+H*(r.c+.025),cx+W*r.xf,ry+H*(r.c+.05));
847	    ctx.stroke();
848	  });
849	  ctx.restore();
850	
851	  // ── LUNG OUTLINES
852	  ctx.save();
853	  ctx.strokeStyle='rgba(90,150,210,.20)';
854	  ctx.lineWidth=Math.max(W*.007,1.5);
855	  ctx.beginPath();
856	  ctx.ellipse(cx-W*.125,H*.34,W*.108,H*.195,-.06,0,Math.PI*2);
857	  ctx.stroke();
858	  ctx.beginPath();
859	  ctx.ellipse(cx+W*.125,H*.34,W*.108,H*.195,.06,0,Math.PI*2);
860	  ctx.stroke();
861	  ctx.restore();
862	
863	  // ── HEART
864	  const hx=cx-W*.04, hy=H*.31, hr=W*.095;
865	
866	  if(mood){
867	    // glow aura
868	    const hg=ctx.createRadialGradient(hx,hy,0,hx,hy,hr*2.6);
869	    hg.addColorStop(0,mood.glowColor);
870	    hg.addColorStop(1,'transparent');
871	    ctx.fillStyle=hg;
872	    ctx.beginPath(); ctx.arc(hx,hy,hr*2.6,0,Math.PI*2); ctx.fill();
873	    // heart shape
874	    drawHeart(ctx,hx,hy,hr,mood.heartColor,1.0);
875	    // mood decoration
876	    mood.draw(ctx,hx,hy,hr,W,H,frame);
877	  } else {
878	    // preview: pulsing outline
879	    const pulse=.85+.15*Math.sin(frame*.08);
880	    drawHeart(ctx,hx,hy,hr*pulse,'rgba(0,212,255,.5)',.5);
881	    ctx.font=`bold ${Math.round(hr*1.0)}px sans-serif`;
882	    ctx.textAlign='center'; ctx.textBaseline='middle';
883	    ctx.fillStyle=`rgba(0,212,255,${.3+.3*Math.sin(frame*.1)})`;
884	    ctx.fillText('?',hx,hy+hr*.1);
885	  }
886	
887	  // ── Watermark
888	  ctx.save();
889	  ctx.font=`${Math.round(W*.025)}px Nanum Gothic,sans-serif`;
890	  ctx.textAlign='left'; ctx.textBaseline='bottom';
891	  ctx.fillStyle='rgba(0,212,255,.25)';
892	  ctx.fillText('💝 마음 X레이 병원', W*.03, H*.97);
893	  ctx.restore();
894	}
