896	/* Heart shape helper */
897	function drawHeart(ctx,x,y,r,color,alpha){
898	  ctx.save();
899	  ctx.globalAlpha=alpha;
900	  ctx.fillStyle=color;
901	  ctx.beginPath();
902	  ctx.moveTo(x, y+r*.3);
903	  ctx.bezierCurveTo(x,   y-r*.3, x-r*1.1, y-r*.3, x-r*1.1, y+r*.25);
904	  ctx.bezierCurveTo(x-r*1.1, y+r*.75, x, y+r*1.2, x, y+r*1.35);
905	  ctx.bezierCurveTo(x, y+r*1.2, x+r*1.1, y+r*.75, x+r*1.1, y+r*.25);
906	  ctx.bezierCurveTo(x+r*1.1, y-r*.3, x, y-r*.3, x, y+r*.3);
907	  ctx.fill();
908	  ctx.restore();
909	}
