  }
})();

/* ─── SCREEN ─────────────────────────────────────── */
function showScreen(id){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

/* ─── CAMERA ─────────────────────────────────────── */
async function startCamera(){
  showScreen('cameraScreen');
  const pvC = document.getElementById('xrayPreviewCanvas');
  const sect = pvC.parentElement;
  pvC.width  = sect.clientWidth  || 400;
  pvC.height = sect.clientHeight || 280;
  animatePv(pvC);

  // BGM 시작 (첫 사용자 인터랙션 후 실행 — iOS/Android 정책 준수)
  BGM.start();
  const btn=document.getElementById('musicBtn');
  btn.classList.remove('off');
  btn.innerHTML='<span class="note-anim">🎵</span>';

  document.getElementById('videoEl').style.display='block';
  document.getElementById('noCam').style.display='none';

  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video:{facingMode:'user',width:{ideal:1280},height:{ideal:720}},
      audio:false
    });
    videoStream = stream;
    const vid = document.getElementById('videoEl');
    vid.srcObject = stream;
  } catch(e){
    console.warn('camera err',e);
    document.getElementById('videoEl').style.display='none';
    document.getElementById('noCam').style.display='flex';
  }
}

/* ─── PREVIEW ANIMATION ──────────────────────────── */
function animatePv(canvas){
  if(pvRafId){cancelAnimationFrame(pvRafId);pvRafId=null;}
  const ctx = canvas.getContext('2d');
  function loop(){
    drawXrayBase(ctx, canvas.width, canvas.height, null, pvFrame++);
    pvRafId = requestAnimationFrame(loop);
  }
  loop();
}
function stopPv(){
  if(pvRafId){cancelAnimationFrame(pvRafId);pvRafId=null;}
}

/* ─── CAPTURE ─────────────────────────────────────── */
function capture(){
  stopPv();
  playShutter();
  doFlash();
  currentMood = MOODS[Math.floor(Math.random()*MOODS.length)];

  // Grab face frame
  const vid = document.getElementById('videoEl');
  const fc = document.createElement('canvas');
  fc.width  = vid.videoWidth  || 640;
  fc.height = vid.videoHeight || 480;
  const fx = fc.getContext('2d');
  fx.save(); fx.scale(-1,1); fx.translate(-fc.width,0);
  try{ fx.drawImage(vid,0,0,fc.width,fc.height); }catch(e){}
  fx.restore();
  faceDataURL = fc.toDataURL('image/jpeg',0.9);

  if(videoStream) videoStream.getTracks().forEach(t=>t.stop());

  setTimeout(buildResult, 380);
}

/* ─── BUILD RESULT ───────────────────────────────── */
function buildResult(){
  showScreen('resultScreen');
  const mood = currentMood;
  const RC = document.getElementById('resultCanvas');
  const W=460, H=680;
  RC.width=W; RC.height=H;
  const ctx = RC.getContext('2d');

  const faceH = Math.round(H*0.40);
  const divH  = 28;
  const xrayY = faceH + divH;
  const xrayH = H - xrayY;

  // 1. Face photo
  const img = new Image();
  img.onload = ()=>{
    ctx.save();
    ctx.beginPath();
    ctx.rect(0,0,W,faceH);
    ctx.clip();
    const sc = Math.max(W/img.naturalWidth, faceH/img.naturalHeight);
    const sw = img.naturalWidth*sc, sh = img.naturalHeight*sc;
    ctx.drawImage(img,(W-sw)/2,(faceH-sh)/2,sw,sh);
    ctx.restore();

    // 2. Divider bar
    ctx.fillStyle='#08101E';
    ctx.fillRect(0,faceH,W,divH);
    const dg = ctx.createLinearGradient(0,0,W,0);
    dg.addColorStop(0,'transparent'); dg.addColorStop(.5,'#00D4FF'); dg.addColorStop(1,'transparent');
    ctx.fillStyle=dg;
    ctx.fillRect(0,faceH+divH/2-1,W,2);
    ctx.fillStyle='#00D4FF';
    ctx.font='bold 13px Nanum Gothic,sans-serif';
    ctx.textAlign='center';
    ctx.textBaseline='middle';
    ctx.fillText('🩻 마음 X레이', W/2, faceH+divH/2);

    // 3. X-ray lower half
    ctx.save();
    ctx.translate(0, xrayY);
    drawXrayBase(ctx, W, xrayH, mood, 0);
    ctx.restore();

    // 4. Mood label strip at bottom
    const lh = 52;
    ctx.fillStyle='rgba(0,0,0,.6)';
    ctx.fillRect(0, H-lh, W, lh);
    ctx.font=`bold ${Math.round(W*0.065)}px Nanum Gothic,sans-serif`;
    ctx.fillStyle=mood.heartColor;
    ctx.shadowColor=mood.heartColor; ctx.shadowBlur=10;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(mood.emoji+' '+mood.name, W/2, H-lh/2);
    ctx.shadowBlur=0;
  };
  img.src = faceDataURL || '';

  // 결과 팡파르 🎉
  setTimeout(playResultJingle, 200);

  document.getElementById('moodEmoji').textContent = mood.emoji;
  document.getElementById('moodName').textContent  = mood.name;
  document.getElementById('moodDesc').textContent  = mood.desc;
  document.getElementById('prescTxt').textContent  = mood.prescription;
}

/* ─── RETAKE ─────────────────────────────────────── */
function retake(){
  pvFrame=0;
  startCamera();
}

