/* ─── STATE ─────────────────────────────────────── */
let currentMood      = null;
let faceDataURL      = null;
let videoStream      = null;
let pvFrame          = 0;
let pvRafId          = null;
let captureInProgress = false;  // 이중 촬영 방지

/* ─── STARS DECO ─────────────────────────────────── */
(function(){
  const cont = document.getElementById('starsDeco');
  const items = ['⭐','🌟','✨','💫','🌸','🎀','💝','🌈','🦋','🩺'];
  for(let i=0;i<16;i++){
    const s = document.createElement('div');
    s.className = 'star-item';
    s.textContent = items[Math.floor(Math.random()*items.length)];
    s.style.left = (Math.random()*88+2)+'%';
    s.style.top  = (Math.random()*88+2)+'%';
    s.style.animationDelay = (Math.random()*3)+'s';
    s.style.fontSize = (16+Math.random()*18)+'px';
    cont.appendChild(s);
  }
})();

/* ─── SCREEN ─────────────────────────────────────── */
function showScreen(id){
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

/* ─── CAMERA ─────────────────────────────────────── */
async function startCamera(){
  captureInProgress = false;

  // ① 화면 전환
  showScreen('cameraScreen');

  // ② 오디오 초기화 (사용자 제스처 직후 — await 이전!)
  ensureAC();
  startBGM();
  const mBtn = document.getElementById('musicBtn');
  mBtn.classList.remove('off');
  mBtn.innerHTML = '<span class="note-anim">🎵</span>';

  // ③ X레이 프리뷰 캔버스 (레이아웃이 잡힌 뒤 크기 측정)
  requestAnimationFrame(() => {
    const pvC  = document.getElementById('xrayPreviewCanvas');
    const sect = pvC.parentElement;
    pvC.width  = sect.clientWidth  || window.innerWidth  || 400;
    pvC.height = sect.clientHeight || Math.round(window.innerHeight * 0.35) || 280;
    animatePv(pvC);
  });

  // ④ 카메라 버튼 초기화
  setCaptureBtn(true);

  // ⑤ 카메라 스트림 요청
  const vid     = document.getElementById('videoEl');
  const noCamEl = document.getElementById('noCam');
  vid.style.display    = 'block';
  noCamEl.style.display = 'none';

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    showCamError('이 브라우저는 카메라를 지원하지 않아요.<br>Chrome 또는 Safari를 사용해주세요.');
    return;
  }

  try {
    // 전면 카메라 우선, 실패 시 기본 카메라
    let stream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width:{ideal:1280}, height:{ideal:720} },
        audio: false
      });
    } catch(e1) {
      stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
    }
    videoStream = stream;
    vid.srcObject = stream;
    await vid.play().catch(()=>{});   // 자동재생 보장

  } catch(err) {
    console.error('카메라 오류:', err.name, err.message);
    let msg = '카메라를 열 수 없어요.';
    if (err.name === 'NotAllowedError')  msg = '📷 카메라 권한을 허용해 주세요!<br>브라우저 주소창 옆 🔒 아이콘을 눌러 카메라를 허용하세요.';
    if (err.name === 'NotFoundError')    msg = '카메라를 찾을 수 없어요.';
    if (err.name === 'NotReadableError') msg = '카메라가 다른 앱에서 사용 중이에요.';
    showCamError(msg);
  }
}

function showCamError(msg) {
  document.getElementById('videoEl').style.display = 'none';
  const el = document.getElementById('noCam');
  el.style.display = 'flex';
  el.querySelector('p').innerHTML = msg;
  setCaptureBtn(false);  // 카메라 없으면 버튼 비활성화
}

function setCaptureBtn(enabled) {
  const btn = document.querySelector('.capture-btn');
  if (!btn) return;
  btn.disabled = !enabled;
  btn.style.opacity = enabled ? '1' : '0.45';
}

/* ─── PREVIEW ANIMATION ──────────────────────────── */
function animatePv(canvas){
  if(pvRafId){ cancelAnimationFrame(pvRafId); pvRafId=null; }
  const ctx = canvas.getContext('2d');
  function loop(){
    drawXrayBase(ctx, canvas.width, canvas.height, null, pvFrame++);
    pvRafId = requestAnimationFrame(loop);
  }
  loop();
}
function stopPv(){
  if(pvRafId){ cancelAnimationFrame(pvRafId); pvRafId=null; }
}

/* ─── CAPTURE ─────────────────────────────────────── */
function capture(){
  if(captureInProgress) return;   // 이중 촬영 방지

  const vid = document.getElementById('videoEl');

  // 카메라가 아직 준비되지 않은 경우 처리
  if(!videoStream || vid.readyState < 2){
    // readyState: 0=HAVE_NOTHING, 1=HAVE_METADATA, 2=HAVE_CURRENT_DATA
    // 카메라가 준비됐을 때 재시도
    vid.addEventListener('canplay', () => capture(), { once: true });
    return;
  }

  captureInProgress = true;
  setCaptureBtn(false);

  // 효과음 + 플래시
  playShutter();
  doFlash();

  // 마음 랜덤 선택
  currentMood = MOODS[Math.floor(Math.random() * MOODS.length)];

  // 얼굴 사진 캡처
  const W = vid.videoWidth  || vid.clientWidth  || 640;
  const H = vid.videoHeight || vid.clientHeight || 480;
  const fc = document.createElement('canvas');
  fc.width = W; fc.height = H;
  const fx = fc.getContext('2d');

  // 거울 반전 (셀피용)
  fx.save();
  fx.translate(W, 0);
  fx.scale(-1, 1);
  try {
    fx.drawImage(vid, 0, 0, W, H);
  } catch(e) {
    console.warn('drawImage 실패:', e.message);
    // 빈 배경으로 대체 (그래도 결과는 보여줌)
    fx.fillStyle = '#222244';
    fx.fillRect(0, 0, W, H);
    fx.fillStyle = 'rgba(255,255,255,0.3)';
    fx.font = `${Math.round(H*0.12)}px sans-serif`;
    fx.textAlign = 'center';
    fx.fillText('📷', W/2, H/2);
  }
  fx.restore();
  faceDataURL = fc.toDataURL('image/jpeg', 0.92);

  // 카메라 스트림 종료
  if(videoStream) {
    videoStream.getTracks().forEach(t => t.stop());
    videoStream = null;
  }
  stopPv();

  setTimeout(buildResult, 400);
}

/* ─── BUILD RESULT ───────────────────────────────── */
function buildResult(){
  showScreen('resultScreen');
  const mood = currentMood;
  const RC = document.getElementById('resultCanvas');
  const W=460, H=680;
  RC.width=W; RC.height=H;
  const ctx = RC.getContext('2d');

  const faceH = Math.round(H * 0.40);
  const divH  = 28;
  const xrayY = faceH + divH;
  const xrayH = H - xrayY;

  // 1. 얼굴 사진
  const img = new Image();
  img.onload = () => {
    // face 영역에 cover fit
    ctx.save();
    ctx.beginPath(); ctx.rect(0,0,W,faceH); ctx.clip();
    const sc = Math.max(W / img.naturalWidth, faceH / img.naturalHeight);
    const sw = img.naturalWidth * sc, sh = img.naturalHeight * sc;
    ctx.drawImage(img, (W-sw)/2, (faceH-sh)/2, sw, sh);
    ctx.restore();

    // 2. 구분선
    ctx.fillStyle='#08101E'; ctx.fillRect(0, faceH, W, divH);
    const dg = ctx.createLinearGradient(0,0,W,0);
    dg.addColorStop(0,'transparent'); dg.addColorStop(.5,'#00D4FF'); dg.addColorStop(1,'transparent');
    ctx.fillStyle=dg; ctx.fillRect(0, faceH+divH/2-1, W, 2);
    ctx.fillStyle='#00D4FF';
    ctx.font='bold 13px Nanum Gothic,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('🩻 마음 X레이', W/2, faceH+divH/2);

    // 3. X레이 하단
    ctx.save(); ctx.translate(0, xrayY);
    drawXrayBase(ctx, W, xrayH, mood, 0);
    ctx.restore();

    // 4. 하단 마음 이름 배너
    const lh = 52;
    ctx.fillStyle='rgba(0,0,0,.6)'; ctx.fillRect(0, H-lh, W, lh);
    ctx.font=`bold ${Math.round(W*0.065)}px Nanum Gothic,sans-serif`;
    ctx.fillStyle=mood.heartColor;
    ctx.shadowColor=mood.heartColor; ctx.shadowBlur=10;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(mood.emoji+' '+mood.name, W/2, H-lh/2);
    ctx.shadowBlur=0;
  };
  img.onerror = () => {
    // 사진 로드 실패해도 X레이는 그림
    ctx.save(); ctx.translate(0, xrayY);
    drawXrayBase(ctx, W, xrayH, mood, 0);
    ctx.restore();
  };
  img.src = faceDataURL || '';

  // 팡파르
  setTimeout(playResultJingle, 180);

  document.getElementById('moodEmoji').textContent = mood.emoji;
  document.getElementById('moodName').textContent  = mood.name;
  document.getElementById('moodDesc').textContent  = mood.desc;
  document.getElementById('prescTxt').textContent  = mood.prescription;
}

/* ─── RETAKE ─────────────────────────────────────── */
function retake(){
  pvFrame = 0;
  faceDataURL = null;
  startCamera();
}

/* ─── FLASH ──────────────────────────────────────── */
function doFlash(){
  const el = document.getElementById('flashOverlay');
  el.classList.add('bang');
  setTimeout(() => el.classList.remove('bang'), 120);
}

