/* ═══════════════════════════════════════════════════
   🎵 BGM ENGINE  (Web Audio API — no external files)
═══════════════════════════════════════════════════ */
const BGM = (() => {
  /* ── 음표 주파수 계산 ── */
  function hz(name, oct){
    const s={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
    return 440*Math.pow(2,(s[name]+(oct-4)*12-9)/12);
  }
  const C3=hz('C',3),G3=hz('G',3),F3=hz('F',3),A3=hz('A',3),E3=hz('E',3);
  const C4=hz('C',4),D4=hz('D',4),E4=hz('E',4),F4=hz('F',4),G4=hz('G',4),A4=hz('A',4);
  const C5=hz('C',5),D5=hz('D',5),E5=hz('E',5),F5=hz('F',5),G5=hz('G',5),A5=hz('A',5);
  const C6=hz('C',6);

  const BPM  = 126;
  const BEAT = 60/BPM; // ≈0.476 s

  /* ── 멜로디: [주파수, 박자]  (0 = 쉼표) ── */
  // 원작 귀여운 동요풍 멜로디 (반짝반짝 작은별 변형 + 마무리)
  const MEL = [
    // 반짝반짝 작은별
    [C5,1],[C5,1],[G5,1],[G5,1],
    [A5,1],[A5,1],[G5,2],
    [F5,1],[F5,1],[E5,1],[E5,1],
    [D5,1],[D5,1],[C5,2],
    // 높은 하늘 위에서
    [G5,1],[G5,1],[F5,1],[F5,1],
    [E5,1],[E5,1],[D5,2],
    [G5,1],[G5,1],[F5,1],[F5,1],
    [E5,1],[E5,1],[D5,2],
    // 다시 반짝반짝
    [C5,1],[C5,1],[G5,1],[G5,1],
    [A5,1],[A5,1],[G5,2],
    [F5,1],[F5,1],[E5,1],[E5,1],
    [D5,1],[D5,1],[C5,2],
  ];

  /* ── 베이스: [주파수, 박자] ── */
  const BASS = [
    [C3,4],[G3,4],[F3,4],[C3,4],
    [G3,4],[F3,4],[G3,4],[G3,4],
    [C3,4],[G3,4],[F3,4],[C3,4],
    [G3,4],[F3,4],[G3,4],[C3,4],
    [C3,4],[G3,4],[F3,4],[C3,4],
    [G3,4],[F3,4],[G3,4],[G3,4],
    [C3,4],[G3,4],[F3,4],[C3,4],
    [F3,4],[G3,4],[C3,4],[C3,4],
  ];

  /* ── 화음 (두 번째 보이스, 3도 아래) ── */
  const HARM = [
    [E4,1],[E4,1],[B4,1],[B4,1],
    [C5,1],[C5,1],[B4,2],
    [A4,1],[A4,1],[G4,1],[G4,1],
    [F4,1],[F4,1],[E4,2],
    [B4,1],[B4,1],[A4,1],[A4,1],
    [G4,1],[G4,1],[F4,2],
    [B4,1],[B4,1],[A4,1],[A4,1],
    [G4,1],[G4,1],[F4,2],
    [E4,1],[E4,1],[B4,1],[B4,1],
    [C5,1],[C5,1],[B4,2],
    [A4,1],[A4,1],[G4,1],[G4,1],
    [F4,1],[F4,1],[E4,2],
  ];

  let ac=null, masterGain=null, playing=false, loopTimer=null;

  function getAC(){
    if(!ac){
      const AC=window.AudioContext||window.webkitAudioContext;
      if(!AC) return null;
      ac=new AC();
      masterGain=ac.createGain();
      masterGain.gain.value=0;
      masterGain.connect(ac.destination);
    }
    return ac;
  }

  function note(freq, t, dur, type, vol){
    if(!freq||!ac) return;
    const osc=ac.createOscillator();
    const g=ac.createGain();
    const atk=Math.min(0.02,dur*.12);
    const rel=Math.min(0.06,dur*.18);
    osc.type=type; osc.frequency.value=freq;
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(vol,t+atk);
    g.gain.setValueAtTime(vol,t+dur-rel);
    g.gain.linearRampToValueAtTime(0,t+dur);
    osc.connect(g); g.connect(masterGain);
    osc.start(t); osc.stop(t+dur+0.06);
  }

  function scheduleLoop(startT){
    if(!playing) return;
    let mt=startT, bt=startT, ht=startT;
    let totalBeats=0;

    MEL.forEach(([f,b])=>{
      note(f, mt, b*BEAT*.86, 'sine', 0.20);
      mt+=b*BEAT; totalBeats+=b;
    });
    BASS.forEach(([f,b])=>{
      note(f, bt, b*BEAT*.70, 'triangle', 0.09);
      bt+=b*BEAT;
    });
    HARM.forEach(([f,b])=>{
      note(f, ht, b*BEAT*.82, 'sine', 0.07);
      ht+=b*BEAT;
    });

    const loopSec=totalBeats*BEAT;
    loopTimer=setTimeout(()=>{ if(playing) scheduleLoop(startT+loopSec); },
      (loopSec-0.5)*1000);
  }

  return {
    start(){
      const a=getAC(); if(!a) return;
      if(a.state==='suspended') a.resume();
      if(playing) return;
      playing=true;
      // 페이드인
      masterGain.gain.cancelScheduledValues(a.currentTime);
      masterGain.gain.setValueAtTime(0,a.currentTime);
      masterGain.gain.linearRampToValueAtTime(0.38,a.currentTime+1.8);
      scheduleLoop(a.currentTime+0.25);
    },
    stop(){
      playing=false;
      if(loopTimer){clearTimeout(loopTimer);loopTimer=null;}
      if(ac&&masterGain){
        masterGain.gain.cancelScheduledValues(ac.currentTime);
        masterGain.gain.setTargetAtTime(0,ac.currentTime,0.35);
      }
    },
    toggle(){
      if(playing){this.stop();return false;}
      else{this.start();return true;}
    },
    isPlaying(){return playing;},
    getAC(){return getAC();}
  };
})();

/* ─── 음악 버튼 토글 ─────────────────────────────── */
function toggleMusic(){
  const on = BGM.toggle();
  const btn = document.getElementById('musicBtn');
  btn.classList.toggle('off',!on);
  btn.innerHTML = on
    ? '<span class="note-anim">🎵</span>'
    : '<span>🔇</span>';
}

/* ═══════════════════════════════════════════════════
   📸 찰칵! 셔터 효과음  (실제 DSLR 카메라 재현)
═══════════════════════════════════════════════════ */
function playShutter(){
  try{
    // BGM AudioContext를 함께 쓰거나 새로 생성
    const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return;
    const ac=BGM.getAC()||new AC();
    if(ac.state==='suspended') ac.resume();
    const t=ac.currentTime;

    /* ── 노이즈 버스트 생성 helper ── */
    function noiseBurst(startT, dur, hpFreq, lpFreq, vol){
      const len=Math.ceil(ac.sampleRate*dur);
      const buf=ac.createBuffer(1,len,ac.sampleRate);
      const d=buf.getChannelData(0);
      for(let i=0;i<len;i++) d[i]=(Math.random()*2-1);
      const src=ac.createBufferSource(); src.buffer=buf;
      const hp=ac.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=hpFreq;
      const lp=ac.createBiquadFilter(); lp.type='lowpass';  lp.frequency.value=lpFreq;
      const g=ac.createGain();
      g.gain.setValueAtTime(vol,startT);
      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
      src.connect(hp); hp.connect(lp); lp.connect(g); g.connect(ac.destination);
      src.start(startT);
    }

    function oscThud(startT, f1, f2, dur, vol){
      const osc=ac.createOscillator();
      const g=ac.createGain();
      osc.frequency.setValueAtTime(f1,startT);
      osc.frequency.exponentialRampToValueAtTime(f2,startT+dur);
      g.gain.setValueAtTime(vol,startT);
      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
      osc.connect(g); g.connect(ac.destination);
      osc.start(startT); osc.stop(startT+dur+0.01);
    }

    // ① 찰— : 미러 올라가는 소리 (저음 쿵 + 중고음 클릭)
    oscThud(t,      220, 35,  0.045, 0.55);   // 쿵
    noiseBurst(t,   0.006, 1800, 8000, 0.80); // 딱

    // ② —칵 : 셔터 블레이드 열림 (날카로운 클릭)
    noiseBurst(t+0.020, 0.004, 3500, 12000, 0.65); // 칵!

    // ③ 셔터 블레이드 닫힘
    noiseBurst(t+0.038, 0.003, 3000, 10000, 0.45);

    // ④ 미러 복귀 (약간 낮고 부드러운 쿵)
    oscThud(t+0.058, 160, 28, 0.040, 0.30);
    noiseBurst(t+0.058, 0.007, 800, 4000, 0.28);

    // ⑤ 금속 울림 (살짝 남는 공명)
    const res=ac.createOscillator();
    const rg=ac.createGain();
    res.type='sine'; res.frequency.value=3200;
    rg.gain.setValueAtTime(0.04,t+0.01);
    rg.gain.exponentialRampToValueAtTime(0.001,t+0.14);
    res.connect(rg); rg.connect(ac.destination);
    res.start(t+0.01); res.stop(t+0.15);

  }catch(e){ console.log('shutter audio err',e); }
}

/* ─── 결과 등장 팡파르 🎉 ────────────────────────── */
function playResultJingle(){
  try{
    const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return;
