    const BEAT=0.11;

    // 상승 아르페지오: C E G C (한 옥타브 위)
    [[523.25,0],[659.25,1],[783.99,2],[1046.50,3]].forEach(([f,i])=>{
      const osc=ac.createOscillator();
      const g=ac.createGain();
      osc.type='sine'; osc.frequency.value=f;
      g.gain.setValueAtTime(0,t+i*BEAT);
      g.gain.linearRampToValueAtTime(0.22,t+i*BEAT+0.025);
      g.gain.exponentialRampToValueAtTime(0.001,t+i*BEAT+0.18);
      osc.connect(g); g.connect(ac.destination);
      osc.start(t+i*BEAT); osc.stop(t+i*BEAT+0.2);
    });
    // 하이 스파클
    [[2093,0.05],[1568,0.12],[2093,0.3]].forEach(([f,d])=>{
