277	<script>
278	'use strict';
279	/* ═══════════════════════════════════════════════════
280	   🎵 오디오 엔진 — BGM·SFX 완전 분리
281	   하나의 AudioContext, 두 개의 독립 게인
282	═══════════════════════════════════════════════════ */
283	let _ac = null;           // 공유 AudioContext
284	let _bgmGain = null;      // BGM 전용 볼륨 (0↔0.38)
285	let _sfxGain = null;      // 효과음 전용 볼륨 (항상 1.0)
286	let _bgmPlaying = false;
287	let _bgmTimer  = null;
288	
289	/* AudioContext 초기화 (첫 사용자 터치 이후 호출) */
290	function initAC() {
291	  if (_ac) return _ac;
292	  const AC = window.AudioContext || window.webkitAudioContext;
293	  if (!AC) return null;
294	  _ac = new AC();
295	
296	  _bgmGain = _ac.createGain(); _bgmGain.gain.value = 0;
297	  _bgmGain.connect(_ac.destination);
298	
299	  _sfxGain = _ac.createGain(); _sfxGain.gain.value = 1.0;
300	  _sfxGain.connect(_ac.destination);
301	
302	  return _ac;
303	}
304	
305	/* AudioContext resume (필수: iOS/Android autoplay 정책) */
306	function ensureAC() {
307	  const ac = initAC();
308	  if (!ac) return null;
309	  if (ac.state === 'suspended') ac.resume();
310	  return ac;
311	}
312	
313	/* ── 음표 주파수 계산 ── */
314	function hz(name, oct) {
315	  const s = {C:0,D:2,E:4,F:5,G:7,A:9,B:11};
316	  return 440 * Math.pow(2, (s[name] + (oct-4)*12 - 9) / 12);
317	}
318	
319	/* ── 반짝반짝 작은별 멜로디 데이터 ── */
320	const BPM  = 124;
321	const BEAT = 60 / BPM;
322	
323	const C3=hz('C',3),G3=hz('G',3),F3=hz('F',3);
324	const C4=hz('C',4),D4=hz('D',4),E4=hz('E',4),F4=hz('F',4),G4=hz('G',4),A4=hz('A',4);
325	const C5=hz('C',5),D5=hz('D',5),E5=hz('E',5),F5=hz('F',5),G5=hz('G',5),A5=hz('A',5);
326	
327	const MEL_SEQ = [
328	  [C5,1],[C5,1],[G5,1],[G5,1],[A5,1],[A5,1],[G5,2],
329	  [F5,1],[F5,1],[E5,1],[E5,1],[D5,1],[D5,1],[C5,2],
330	  [G5,1],[G5,1],[F5,1],[F5,1],[E5,1],[E5,1],[D5,2],
331	  [G5,1],[G5,1],[F5,1],[F5,1],[E5,1],[E5,1],[D5,2],
332	  [C5,1],[C5,1],[G5,1],[G5,1],[A5,1],[A5,1],[G5,2],
333	  [F5,1],[F5,1],[E5,1],[E5,1],[D5,1],[D5,1],[C5,2],
334	];
335	const BASS_SEQ = [
336	  [C3,4],[G3,4],[F3,4],[C3,4],[G3,4],[F3,4],[G3,4],[C3,4],
337	  [C3,4],[G3,4],[F3,4],[C3,4],[G3,4],[F3,4],[G3,4],[C3,4],
338	  [C3,4],[G3,4],[F3,4],[C3,4],[G3,4],[F3,4],[G3,4],[C3,4],
339	];
340	const HARM_SEQ = [
341	  [E4,1],[E4,1],[B4,1],[B4,1],[C5,1],[C5,1],[B4,2],
342	  [A4,1],[A4,1],[G4,1],[G4,1],[F4,1],[F4,1],[E4,2],
343	  [B4,1],[B4,1],[A4,1],[A4,1],[G4,1],[G4,1],[F4,2],
344	  [B4,1],[B4,1],[A4,1],[A4,1],[G4,1],[G4,1],[F4,2],
345	  [E4,1],[E4,1],[B4,1],[B4,1],[C5,1],[C5,1],[B4,2],
346	  [A4,1],[A4,1],[G4,1],[G4,1],[F4,1],[F4,1],[E4,2],
347	];
348	
349	function schedNote(freq, startT, dur, type, vol, dest) {
350	  if (!freq || !_ac || !dest) return;
351	  const osc = _ac.createOscillator();
352	  const g   = _ac.createGain();
353	  const atk = Math.min(0.02, dur * 0.12);
354	  const rel = Math.min(0.06, dur * 0.18);
355	  osc.type = type;
356	  osc.frequency.value = freq;
357	  g.gain.setValueAtTime(0, startT);
358	  g.gain.linearRampToValueAtTime(vol, startT + atk);
359	  g.gain.setValueAtTime(vol, startT + dur - rel);
360	  g.gain.linearRampToValueAtTime(0, startT + dur);
361	  osc.connect(g); g.connect(dest);
362	  osc.start(startT); osc.stop(startT + dur + 0.05);
363	}
364	
365	function scheduleBGMLoop(startT) {
366	  if (!_bgmPlaying || !_ac) return;
367	  let mt = startT, bt = startT, ht = startT;
368	  let totalBeats = 0;
369	
370	  MEL_SEQ.forEach(([f,b]) => {
371	    schedNote(f, mt, b*BEAT*0.85, 'sine',     0.20, _bgmGain);
372	    mt += b*BEAT; totalBeats += b;
373	  });
374	  BASS_SEQ.forEach(([f,b]) => {
375	    schedNote(f, bt, b*BEAT*0.70, 'triangle', 0.09, _bgmGain);
376	    bt += b*BEAT;
377	  });
378	  HARM_SEQ.forEach(([f,b]) => {
379	    schedNote(f, ht, b*BEAT*0.80, 'sine',     0.07, _bgmGain);
380	    ht += b*BEAT;
381	  });
382	
383	  const loopSec = totalBeats * BEAT;
384	  _bgmTimer = setTimeout(() => {
385	    if (_bgmPlaying) scheduleBGMLoop(startT + loopSec);
386	  }, (loopSec - 0.5) * 1000);
387	}
388	
389	function startBGM() {
390	  const ac = ensureAC(); if (!ac) return;
391	  if (_bgmPlaying) return;
392	  _bgmPlaying = true;
393	  _bgmGain.gain.cancelScheduledValues(ac.currentTime);
394	  _bgmGain.gain.setValueAtTime(0, ac.currentTime);
395	  _bgmGain.gain.linearRampToValueAtTime(0.38, ac.currentTime + 1.8);
396	  scheduleBGMLoop(ac.currentTime + 0.2);
397	}
398	
399	function stopBGM() {
400	  _bgmPlaying = false;
401	  if (_bgmTimer) { clearTimeout(_bgmTimer); _bgmTimer = null; }
402	  if (_ac && _bgmGain) {
403	    _bgmGain.gain.cancelScheduledValues(_ac.currentTime);
404	    _bgmGain.gain.setTargetAtTime(0, _ac.currentTime, 0.3);
405	  }
406	}
407	
408	function toggleMusic() {
409	  const btn = document.getElementById('musicBtn');
410	  if (_bgmPlaying) {
411	    stopBGM();
412	    btn.classList.add('off');
413	    btn.innerHTML = '<span>🔇</span>';
414	  } else {
415	    startBGM();
416	    btn.classList.remove('off');
417	    btn.innerHTML = '<span class="note-anim">🎵</span>';
418	  }
419	}
420	
421	/* ── 📸 찰칵! 셔터 효과음 ── */
422	function playShutter() {
423	  const ac = ensureAC(); if (!ac) return;
424	  const t = ac.currentTime;
425	
426	  function noiseBurst(startT, dur, hp, lp, vol) {
427	    try {
428	      const len = Math.max(1, Math.ceil(ac.sampleRate * dur));
429	      const buf = ac.createBuffer(1, len, ac.sampleRate);
430	      const d = buf.getChannelData(0);
431	      for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1);
432	      const src = ac.createBufferSource(); src.buffer = buf;
433	      const hpF = ac.createBiquadFilter(); hpF.type='highpass'; hpF.frequency.value=hp;
434	      const lpF = ac.createBiquadFilter(); lpF.type='lowpass';  lpF.frequency.value=lp;
435	      const g = ac.createGain();
436	      g.gain.setValueAtTime(vol, startT);
437	      g.gain.exponentialRampToValueAtTime(0.001, startT + dur);
438	      src.connect(hpF); hpF.connect(lpF); lpF.connect(g); g.connect(_sfxGain);
439	      src.start(startT);
440	    } catch(e) {}
441	  }
442	
443	  function oscThud(startT, f1, f2, dur, vol) {
444	    try {
445	      const osc = ac.createOscillator();
446	      const g   = ac.createGain();
447	      osc.frequency.setValueAtTime(f1, startT);
448	      osc.frequency.exponentialRampToValueAtTime(f2, startT + dur);
449	      g.gain.setValueAtTime(vol, startT);
450	      g.gain.exponentialRampToValueAtTime(0.001, startT + dur);
451	      osc.connect(g); g.connect(_sfxGain);
452	      osc.start(startT); osc.stop(startT + dur + 0.01);
453	    } catch(e) {}
454	  }
455	
456	  // ① 찰— 미러 올라가는 소리
457	  oscThud(t,       220, 35,  0.045, 0.60);
458	  noiseBurst(t,    0.006, 1800, 8000, 0.90);
459	  // ② —칵 셔터 블레이드 열림
460	  noiseBurst(t+0.022, 0.004, 3500, 12000, 0.70);
461	  // ③ 셔터 블레이드 닫힘
462	  noiseBurst(t+0.040, 0.003, 3000, 10000, 0.50);
463	  // ④ 미러 복귀
464	  oscThud(t+0.060, 160, 28, 0.040, 0.35);
465	  noiseBurst(t+0.060, 0.007, 800, 4000, 0.30);
466	  // ⑤ 금속 공명
467	  try {
468	    const res = ac.createOscillator(), rg = ac.createGain();
469	    res.type = 'sine'; res.frequency.value = 3200;
470	    rg.gain.setValueAtTime(0.05, t+0.01);
471	    rg.gain.exponentialRampToValueAtTime(0.001, t+0.15);
472	    res.connect(rg); rg.connect(_sfxGain);
473	    res.start(t+0.01); res.stop(t+0.16);
474	  } catch(e) {}
475	}
476	
477	/* ── 🎉 결과 등장 팡파르 ── */
478	function playResultJingle() {
479	  const ac = ensureAC(); if (!ac) return;
480	  const t = ac.currentTime + 0.1;
481	  const B = 0.11;
482	  [[523.25,0],[659.25,1],[783.99,2],[1046.50,3]].forEach(([f,i]) => {
483	    try {
484	      const osc=ac.createOscillator(), g=ac.createGain();
485	      osc.type='sine'; osc.frequency.value=f;
486	      g.gain.setValueAtTime(0, t+i*B);
487	      g.gain.linearRampToValueAtTime(0.25, t+i*B+0.025);
488	      g.gain.exponentialRampToValueAtTime(0.001, t+i*B+0.2);
489	      osc.connect(g); g.connect(_sfxGain);
490	      osc.start(t+i*B); osc.stop(t+i*B+0.22);
491	    } catch(e) {}
492	  });
493	  [[2093,0.06],[1568,0.13],[2093,0.32]].forEach(([f,d]) => {
494	    try {
495	      const o=ac.createOscillator(), g=ac.createGain();
496	      o.type='sine'; o.frequency.value=f;
497	      g.gain.setValueAtTime(0.09,t+d); g.gain.exponentialRampToValueAtTime(0.001,t+d+0.08);
498	      o.connect(g); g.connect(_sfxGain);
499	      o.start(t+d); o.stop(t+d+0.09);
500	    } catch(e) {}
501	  });
502	}
