604	async function startCamera(){
605	  captureInProgress = false;
606	
607	  // ① 화면 전환
608	  showScreen('cameraScreen');
609	
610	  // ② 오디오 초기화 (사용자 제스처 직후 — await 이전!)
611	  ensureAC();
612	  startBGM();
613	  const mBtn = document.getElementById('musicBtn');
614	  mBtn.classList.remove('off');
615	  mBtn.innerHTML = '<span class="note-anim">🎵</span>';
616	
617	  // ③ X레이 프리뷰 캔버스 (레이아웃이 잡힌 뒤 크기 측정)
618	  requestAnimationFrame(() => {
619	    const pvC  = document.getElementById('xrayPreviewCanvas');
620	    const sect = pvC.parentElement;
621	    pvC.width  = sect.clientWidth  || window.innerWidth  || 400;
622	    pvC.height = sect.clientHeight || Math.round(window.innerHeight * 0.35) || 280;
623	    animatePv(pvC);
624	  });
625	
626	  // ④ 카메라 버튼 초기화
627	  setCaptureBtn(true);
628	
629	  // ⑤ 카메라 스트림 요청
630	  const vid     = document.getElementById('videoEl');
631	  const noCamEl = document.getElementById('noCam');
632	  vid.style.display    = 'block';
633	  noCamEl.style.display = 'none';
634	
635	  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
636	    showCamError('이 브라우저는 카메라를 지원하지 않아요.<br>Chrome 또는 Safari를 사용해주세요.');
637	    return;
638	  }
639	
640	  try {
641	    // 전면 카메라 우선, 실패 시 기본 카메라
642	    let stream;
643	    try {
644	      stream = await navigator.mediaDevices.getUserMedia({
645	        video: { facingMode: 'user', width:{ideal:1280}, height:{ideal:720} },
646	        audio: false
647	      });
648	    } catch(e1) {
649	      stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
650	    }
651	    videoStream = stream;
652	    vid.srcObject = stream;
653	    await vid.play().catch(()=>{});   // 자동재생 보장
654	
655	  } catch(err) {
656	    console.error('카메라 오류:', err.name, err.message);
657	    let msg = '카메라를 열 수 없어요.';
658	    if (err.name === 'NotAllowedError')  msg = '📷 카메라 권한을 허용해 주세요!<br>브라우저 주소창 옆 🔒 아이콘을 눌러 카메라를 허용하세요.';
659	    if (err.name === 'NotFoundError')    msg = '카메라를 찾을 수 없어요.';
660	    if (err.name === 'NotReadableError') msg = '카메라가 다른 앱에서 사용 중이에요.';
661	    showCamError(msg);
662	  }
663	}
