680	/* ─── PREVIEW ANIMATION ──────────────────────────── */
681	function animatePv(canvas){
682	  if(pvRafId){ cancelAnimationFrame(pvRafId); pvRafId=null; }
683	  const ctx = canvas.getContext('2d');
684	  function loop(){
685	    drawXrayBase(ctx, canvas.width, canvas.height, null, pvFrame++);
686	    pvRafId = requestAnimationFrame(loop);
687	  }
688	  loop();
689	}
690	function stopPv(){
691	  if(pvRafId){ cancelAnimationFrame(pvRafId); pvRafId=null; }
692	}
