694	/* ─── CAPTURE ─────────────────────────────────────── */
695	function capture(){
696	  if(captureInProgress) return;   // 이중 촬영 방지
697	
698	  const vid = document.getElementById('videoEl');
699	
700	  // 카메라가 아직 준비되지 않은 경우 처리
701	  if(!videoStream || vid.readyState < 2){
702	    // readyState: 0=HAVE_NOTHING, 1=HAVE_METADATA, 2=HAVE_CURRENT_DATA
703	    // 카메라가 준비됐을 때 재시도
704	    vid.addEventListener('canplay', () => capture(), { once: true });
705	    return;
706	  }
707	
708	  captureInProgress = true;
709	  setCaptureBtn(false);
710	
711	  // 효과음 + 플래시
712	  playShutter();
713	  doFlash();
714	
715	  // 마음 랜덤 선택
716	  currentMood = MOODS[Math.floor(Math.random() * MOODS.length)];
717	
718	  // 얼굴 사진 캡처
719	  const W = vid.videoWidth  || vid.clientWidth  || 640;
720	  const H = vid.videoHeight || vid.clientHeight || 480;
721	  const fc = document.createElement('canvas');
722	  fc.width = W; fc.height = H;
723	  const fx = fc.getContext('2d');
724	
725	  // 거울 반전 (셀피용)
726	  fx.save();
727	  fx.translate(W, 0);
728	  fx.scale(-1, 1);
729	  try {
730	    fx.drawImage(vid, 0, 0, W, H);
731	  } catch(e) {
732	    console.warn('drawImage 실패:', e.message);
733	    // 빈 배경으로 대체 (그래도 결과는 보여줌)
734	    fx.fillStyle = '#222244';
735	    fx.fillRect(0, 0, W, H);
736	    fx.fillStyle = 'rgba(255,255,255,0.3)';
737	    fx.font = `${Math.round(H*0.12)}px sans-serif`;
738	    fx.textAlign = 'center';
739	    fx.fillText('📷', W/2, H/2);
740	  }
741	  fx.restore();
742	  faceDataURL = fc.toDataURL('image/jpeg', 0.92);
743	
744	  // 카메라 스트림 종료
745	  if(videoStream) {
746	    videoStream.getTracks().forEach(t => t.stop());
747	    videoStream = null;
748	  }
749	  stopPv();
750	
751	  setTimeout(buildResult, 400);
752	}
