754	/* ─── BUILD RESULT ───────────────────────────────── */
755	function buildResult(){
756	  showScreen('resultScreen');
757	  const mood = currentMood;
758	  const RC = document.getElementById('resultCanvas');
759	  const W=460, H=680;
760	  RC.width=W; RC.height=H;
761	  const ctx = RC.getContext('2d');
762	
763	  const faceH = Math.round(H * 0.40);
764	  const divH  = 28;
765	  const xrayY = faceH + divH;
766	  const xrayH = H - xrayY;
767	
768	  // 1. 얼굴 사진
769	  const img = new Image();
770	  img.onload = () => {
771	    // face 영역에 cover fit
772	    ctx.save();
773	    ctx.beginPath(); ctx.rect(0,0,W,faceH); ctx.clip();
774	    const sc = Math.max(W / img.naturalWidth, faceH / img.naturalHeight);
775	    const sw = img.naturalWidth * sc, sh = img.naturalHeight * sc;
776	    ctx.drawImage(img, (W-sw)/2, (faceH-sh)/2, sw, sh);
777	    ctx.restore();
778	
779	    // 2. 구분선
780	    ctx.fillStyle='#08101E'; ctx.fillRect(0, faceH, W, divH);
781	    const dg = ctx.createLinearGradient(0,0,W,0);
782	    dg.addColorStop(0,'transparent'); dg.addColorStop(.5,'#00D4FF'); dg.addColorStop(1,'transparent');
783	    ctx.fillStyle=dg; ctx.fillRect(0, faceH+divH/2-1, W, 2);
784	    ctx.fillStyle='#00D4FF';
785	    ctx.font='bold 13px Nanum Gothic,sans-serif';
786	    ctx.textAlign='center'; ctx.textBaseline='middle';
787	    ctx.fillText('🩻 마음 X레이', W/2, faceH+divH/2);
788	
789	    // 3. X레이 하단
790	    ctx.save(); ctx.translate(0, xrayY);
791	    drawXrayBase(ctx, W, xrayH, mood, 0);
792	    ctx.restore();
793	
794	    // 4. 하단 마음 이름 배너
795	    const lh = 52;
796	    ctx.fillStyle='rgba(0,0,0,.6)'; ctx.fillRect(0, H-lh, W, lh);
797	    ctx.font=`bold ${Math.round(W*0.065)}px Nanum Gothic,sans-serif`;
798	    ctx.fillStyle=mood.heartColor;
799	    ctx.shadowColor=mood.heartColor; ctx.shadowBlur=10;
800	    ctx.textAlign='center'; ctx.textBaseline='middle';
801	    ctx.fillText(mood.emoji+' '+mood.name, W/2, H-lh/2);
802	    ctx.shadowBlur=0;
803	  };
804	  img.onerror = () => {
805	    // 사진 로드 실패해도 X레이는 그림
806	    ctx.save(); ctx.translate(0, xrayY);
807	    drawXrayBase(ctx, W, xrayH, mood, 0);
808	    ctx.restore();
809	  };
810	  img.src = faceDataURL || '';
811	
812	  // 팡파르
813	  setTimeout(playResultJingle, 180);
814	
815	  document.getElementById('moodEmoji').textContent = mood.emoji;
816	  document.getElementById('moodName').textContent  = mood.name;
817	  document.getElementById('moodDesc').textContent  = mood.desc;
818	  document.getElementById('prescTxt').textContent  = mood.prescription;
819	}
