835	/* ═══════════════════════════════════════════════════
836	   X-RAY DRAWING
837	═══════════════════════════════════════════════════ */
838	function drawXrayBase(ctx, W, H, mood, frame){
839	  // Background
840	  ctx.fillStyle='#030A18';
841	  ctx.fillRect(0,0,W,H);
842	
843	  // Scanlines
844	  for(let y=0;y<H;y+=3){
845	    ctx.fillStyle='rgba(0,50,120,.014)';
846	    ctx.fillRect(0,y,W,1);
847	  }
848	
849	  // Center glow
850	  const cGlow = ctx.createRadialGradient(W/2,H*.38,0,W/2,H*.38,W*.5);
851	  const gc = mood ? mood.glowColor : 'rgba(0,100,180,0.1)';
852	  cGlow.addColorStop(0,gc.replace(/[\d.]+\)$/,'0.1)'));
853	  cGlow.addColorStop(1,'transparent');
854	  ctx.fillStyle=cGlow; ctx.fillRect(0,0,W,H);
855	
856	  const cx=W/2;
857	
858	  // ── SPINE vertebrae
859	  for(let i=0;i<11;i++){
860	    const sy=H*.09+i*H*.062;
861	    const sw=W*.026+i*W*.0008;
862	    ctx.fillStyle=`rgba(150,200,255,${Math.min(.3+i*.015,.5)})`;
863	    ctx.strokeStyle=`rgba(190,225,255,${Math.min(.35+i*.015,.55)})`;
864	    ctx.lineWidth=.8;
865	    ctx.beginPath();
866	    if(ctx.roundRect) ctx.roundRect(cx-sw,sy-H*.018,sw*2,H*.034,3);
867	    else ctx.rect(cx-sw,sy-H*.018,sw*2,H*.034);
868	    ctx.fill(); ctx.stroke();
869	  }
870	
871	  // ── CLAVICLES
872	  ctx.save();
873	  ctx.strokeStyle='rgba(175,215,255,.72)';
874	  ctx.lineWidth=Math.max(W*.010,2);
875	  ctx.lineCap='round';
876	  ctx.beginPath();
877	  ctx.moveTo(cx-W*.04,H*.10);
878	  ctx.bezierCurveTo(cx-W*.12,H*.08,cx-W*.22,H*.10,cx-W*.30,H*.155);
879	  ctx.stroke();
880	  ctx.beginPath();
881	  ctx.moveTo(cx+W*.04,H*.10);
882	  ctx.bezierCurveTo(cx+W*.12,H*.08,cx+W*.22,H*.10,cx+W*.30,H*.155);
883	  ctx.stroke();
884	  ctx.restore();
885	
886	  // ── RIBS
887	  const ribs=[
888	    {y:.17,xf:.26,c:-.018},{y:.24,xf:.29,c:-.008},{y:.31,xf:.31,c:.000},
889	    {y:.38,xf:.30,c:.012},{y:.45,xf:.27,c:.024},{y:.51,xf:.23,c:.034},
890	  ];
891	  ctx.save();
892	  ctx.lineWidth=Math.max(W*.008,1.5);
893	  ctx.lineCap='round';
894	  ribs.forEach((r,i)=>{
895	    const ry=H*r.y;
896	    const al=(.55-i*.04);
897	    ctx.strokeStyle=`rgba(155,205,255,${al})`;
898	    ctx.beginPath();
899	    ctx.moveTo(cx-W*.035,ry);
900	    ctx.bezierCurveTo(cx-W*.11,ry+H*r.c,cx-W*(r.xf-.04),ry+H*(r.c+.025),cx-W*r.xf,ry+H*(r.c+.05));
901	    ctx.stroke();
902	    ctx.beginPath();
903	    ctx.moveTo(cx+W*.035,ry);
904	    ctx.bezierCurveTo(cx+W*.11,ry+H*r.c,cx+W*(r.xf-.04),ry+H*(r.c+.025),cx+W*r.xf,ry+H*(r.c+.05));
905	    ctx.stroke();
906	  });
907	  ctx.restore();
908	
909	  // ── LUNG OUTLINES
910	  ctx.save();
911	  ctx.strokeStyle='rgba(90,150,210,.20)';
912	  ctx.lineWidth=Math.max(W*.007,1.5);
913	  ctx.beginPath();
914	  ctx.ellipse(cx-W*.125,H*.34,W*.108,H*.195,-.06,0,Math.PI*2);
915	  ctx.stroke();
916	  ctx.beginPath();
917	  ctx.ellipse(cx+W*.125,H*.34,W*.108,H*.195,.06,0,Math.PI*2);
918	  ctx.stroke();
919	  ctx.restore();
920	
921	  // ── HEART
922	  const hx=cx-W*.04, hy=H*.31, hr=W*.095;
923	
924	  if(mood){
925	    // glow aura
926	    const hg=ctx.createRadialGradient(hx,hy,0,hx,hy,hr*2.6);
927	    hg.addColorStop(0,mood.glowColor);
928	    hg.addColorStop(1,'transparent');
929	    ctx.fillStyle=hg;
930	    ctx.beginPath(); ctx.arc(hx,hy,hr*2.6,0,Math.PI*2); ctx.fill();
931	    // heart shape
932	    drawHeart(ctx,hx,hy,hr,mood.heartColor,1.0);
933	    // mood decoration
934	    mood.draw(ctx,hx,hy,hr,W,H,frame);
935	  } else {
936	    // preview: pulsing outline
937	    const pulse=.85+.15*Math.sin(frame*.08);
938	    drawHeart(ctx,hx,hy,hr*pulse,'rgba(0,212,255,.5)',.5);
939	    ctx.font=`bold ${Math.round(hr*1.0)}px sans-serif`;
940	    ctx.textAlign='center'; ctx.textBaseline='middle';
941	    ctx.fillStyle=`rgba(0,212,255,${.3+.3*Math.sin(frame*.1)})`;
942	    ctx.fillText('?',hx,hy+hr*.1);
943	  }
944	
945	  // ── Watermark
946	  ctx.save();
947	  ctx.font=`${Math.round(W*.025)}px Nanum Gothic,sans-serif`;
948	  ctx.textAlign='left'; ctx.textBaseline='bottom';
949	  ctx.fillStyle='rgba(0,212,255,.25)';
950	  ctx.fillText('💝 마음 X레이 병원', W*.03, H*.97);
951	  ctx.restore();
952	}
953	
954	/* Heart shape helper */
955	function drawHeart(ctx,x,y,r,color,alpha){
956	  ctx.save();
957	  ctx.globalAlpha=alpha;
958	  ctx.fillStyle=color;
959	  ctx.beginPath();
960	  ctx.moveTo(x, y+r*.3);
961	  ctx.bezierCurveTo(x,   y-r*.3, x-r*1.1, y-r*.3, x-r*1.1, y+r*.25);
962	  ctx.bezierCurveTo(x-r*1.1, y+r*.75, x, y+r*1.2, x, y+r*1.35);
963	  ctx.bezierCurveTo(x, y+r*1.2, x+r*1.1, y+r*.75, x+r*1.1, y+r*.25);
964	  ctx.bezierCurveTo(x+r*1.1, y-r*.3, x, y-r*.3, x, y+r*.3);
965	  ctx.fill();
966	  ctx.restore();
967	}
