978	    ctx.beginPath(); ctx.ellipse(tx,ty,hr*.09,hr*.14,0,0,Math.PI*2); ctx.fill();
979	    ctx.restore();
980	  });
981	  // rain streaks
982	  for(let i=0;i<7;i++){
983	    const rx=hx+(i-3.5)*hr*.3;
