1099	function drawShy(ctx,hx,hy,hr,W,H,f){
1100	  [[-1,.3],[1,.3]].forEach(([bx,by])=>{
1101	    const g=ctx.createRadialGradient(hx+bx*hr,hy+by*hr,0,hx+bx*hr,hy+by*hr,hr*.55);
1102	    g.addColorStop(0,'rgba(255,140,140,.55)'); g.addColorStop(1,'transparent');
1103	    ctx.fillStyle=g;
1104	    ctx.beginPath(); ctx.ellipse(hx+bx*hr,hy+by*hr,hr*.55,hr*.38,0,0,Math.PI*2); ctx.fill();
1105	  });
1106	  [[hx-hr*1.55,hy-hr*.75],[hx+hr*1.45,hy-hr*1.05],[hx+hr*.05,hy-hr*2.0]].forEach(([fx,fy])=>{
1107	    drawFlower(ctx,fx,fy,hr*.22,'#FD79A8');
