1128	  ctx.setLineDash([]); ctx.restore();
1129	  [[hx-hr*2.3,hy-hr*1.2],[hx+hr*2.1,hy-hr*.85],[hx-hr*1.9,hy+hr*1.35],
1130	   [hx+hr*1.6,hy+hr*1.6],[hx+hr*.05,hy-hr*2.3]].forEach(([sx,sy])=>{
1131	    const p=.4+.4*Math.sin(f*.05+sx*.01);
1132	    ctx.save(); ctx.globalAlpha=p*.65; ctx.fillStyle='#C8B4FF';
1133	    ctx.beginPath(); ctx.arc(sx,sy,hr*.1,0,Math.PI*2); ctx.fill(); ctx.restore();
