1144	  ctx.lineTo(gx+sw+gr,gy+gr*.9);
1145	  ctx.bezierCurveTo(gx+sw+gr*.62,gy+gr*.5,gx+sw+gr*.22,gy+gr*1.12,gx+sw,gy+gr*.72);
1146	  ctx.bezierCurveTo(gx+sw-gr*.22,gy+gr*1.12,gx+sw-gr*.62,gy+gr*.5,gx+sw-gr,gy+gr*.9);
1147	  ctx.closePath(); ctx.fill();
1148	  ctx.fillStyle='#06101E'; ctx.globalAlpha=.92;
1149	  ctx.beginPath(); ctx.ellipse(gx+sw-gr*.3,gy-gr*.05,gr*.17,gr*.22,0,0,Math.PI*2); ctx.fill();
1150	  ctx.beginPath(); ctx.ellipse(gx+sw+gr*.3,gy-gr*.05,gr*.17,gr*.22,0,0,Math.PI*2); ctx.fill();
1151	  ctx.restore();
1152	  for(let i=0;i<6;i++){
1153	    const ang=(i*60+f*4)*Math.PI/180;
