function schedNote(freq, startT, dur, type, vol, dest) {
  if (!freq || !_ac || !dest) return;
  const osc = _ac.createOscillator();
  const g   = _ac.createGain();
  const atk = 0.012;                        // 피아노 어택: 짧고 선명
  const rel = Math.min(dur * 0.65, 1.0);   // 피아노 릴리즈: 긴 여운
  osc.type = type;
  osc.frequency.value = freq;
  g.gain.setValueAtTime(0, startT);
  g.gain.linearRampToValueAtTime(vol, startT + atk);
  g.gain.exponentialRampToValueAtTime(vol * 0.30, startT + dur);
  g.gain.linearRampToValueAtTime(0, startT + dur + rel);
  osc.connect(g); g.connect(dest);
  osc.start(startT); osc.stop(startT + dur + rel + 0.08);
}

