277	<script>
278	/* ═══════════════════════════════════════════════════
279	   🎵 오디오 엔진 — BGM·SFX 완전 분리
280	   하나의 AudioContext, 두 개의 독립 게인
281	═══════════════════════════════════════════════════ */
282	let _ac = null;           // 공유 AudioContext
283	let _bgmGain = null;      // BGM 전용 볼륨 (0↔0.38)
284	let _sfxGain = null;      // 효과음 전용 볼륨 (항상 1.0)
285	let _bgmPlaying = false;
286	let _bgmTimer  = null;
287	
288	/* AudioContext 초기화 (첫 사용자 터치 이후 호출) */
289	function initAC() {
290	  if (_ac) return _ac;
291	  const AC = window.AudioContext || window.webkitAudioContext;
292	  if (!AC) return null;
293	  _ac = new AC();
294	
295	  _bgmGain = _ac.createGain(); _bgmGain.gain.value = 0;
296	  _bgmGain.connect(_ac.destination);
297	
298	  _sfxGain = _ac.createGain(); _sfxGain.gain.value = 1.0;
299	  _sfxGain.connect(_ac.destination);
300	
301	  return _ac;
302	}
303	
304	/* AudioContext resume (필수: iOS/Android autoplay 정책) */
305	function ensureAC() {
306	  const ac = initAC();
307	  if (!ac) return null;
308	  if (ac.state === 'suspended') ac.resume();
309	  return ac;
310	}
311	
312	/* ── 음표 주파수 계산 ── */
313	function hz(name, oct) {
314	  const s = {C:0,D:2,E:4,F:5,G:7,A:9,B:11};
315	  return 440 * Math.pow(2, (s[name] + (oct-4)*12 - 9) / 12);
316	}
317	
318	/* ── 지브리풍 잔잔한 BGM (C장조, 72 BPM) ── */
319	const BPM  = 72;
320	const BEAT = 60 / BPM;
321	
322	// 전체 음역 선언 (3~5옥타브)
323	const C3=hz('C',3),D3=hz('D',3),E3=hz('E',3),F3=hz('F',3),G3=hz('G',3),A3=hz('A',3),B3=hz('B',3);
324	const C4=hz('C',4),D4=hz('D',4),E4=hz('E',4),F4=hz('F',4),G4=hz('G',4),A4=hz('A',4),B4=hz('B',4);
325	const C5=hz('C',5),D5=hz('D',5),E5=hz('E',5),F5=hz('F',5),G5=hz('G',5),A5=hz('A',5),B5=hz('B',5);
326	
327	// 멜로디 (오른손 — 잔잔하고 흐르는 선율 48박)
328	const MEL_SEQ = [
329	  // A 악절 — 가볍게 시작
330	  [E5,1],[D5,1],[C5,2],
331	  [D5,1],[E5,1],[G5,2],
332	  [F5,2],[E5,2],
333	  [C5,4],
334	  // B 악절 — 조금 높아짐
335	  [G5,1],[F5,1],[E5,2],
336	  [D5,2],[C5,2],
337	  [E5,1],[G5,1],[A5,2],
338	  [G5,4],
339	  // C 악절 — 여운 있게 마무리
340	  [E5,1],[D5,1],[C5,2],
341	  [F5,2],[G5,2],
342	  [A5,1],[G5,1],[E5,2],
343	  [C5,4],
344	];
345	
346	// 베이스 (왼손 — 낮고 따뜻한 반주 48박)
347	const BASS_SEQ = [
348	  [C3,2],[G3,2],[C3,2],[G3,2],
349	  [F3,2],[C3,2],[C3,4],
350	  [G3,2],[G3,2],[F3,2],[C3,2],
351	  [F3,2],[G3,2],[G3,4],
352	  [C3,2],[G3,2],[F3,4],
353	  [F3,2],[G3,2],[C3,4],
354	];
355	
356	// 하모니 (내성 — 부드러운 화음 48박)
357	const HARM_SEQ = [
358	  [G4,2],[E4,2],[F4,2],[G4,2],
359	  [A4,2],[G4,2],[E4,4],
360	  [B4,2],[G4,2],[A4,2],[F4,2],
361	  [C5,2],[A4,2],[D4,4],
362	  [G4,2],[E4,2],[A4,2],[C5,2],
363	  [C5,2],[G4,2],[E4,4],
364	];
365	
366	function schedNote(freq, startT, dur, type, vol, dest) {
367	  if (!freq || !_ac || !dest) return;
368	  const osc = _ac.createOscillator();
369	  const g   = _ac.createGain();
370	  const atk = 0.012;                        // 피아노 어택: 짧고 선명
371	  const rel = Math.min(dur * 0.65, 1.0);   // 피아노 릴리즈: 긴 여운
372	  osc.type = type;
373	  osc.frequency.value = freq;
374	  g.gain.setValueAtTime(0, startT);
375	  g.gain.linearRampToValueAtTime(vol, startT + atk);
376	  g.gain.exponentialRampToValueAtTime(vol * 0.30, startT + dur);
377	  g.gain.linearRampToValueAtTime(0, startT + dur + rel);
378	  osc.connect(g); g.connect(dest);
379	  osc.start(startT); osc.stop(startT + dur + rel + 0.08);
380	}
381	
382	function scheduleBGMLoop(startT) {
383	  if (!_bgmPlaying || !_ac) return;
384	  let mt = startT, bt = startT, ht = startT;
385	  let totalBeats = 0;
386	
387	  MEL_SEQ.forEach(([f,b]) => {
388	    schedNote(f, mt, b*BEAT*0.85, 'sine',     0.20, _bgmGain);
389	    mt += b*BEAT; totalBeats += b;
390	  });
391	  BASS_SEQ.forEach(([f,b]) => {
392	    schedNote(f, bt, b*BEAT*0.70, 'triangle', 0.09, _bgmGain);
393	    bt += b*BEAT;
394	  });
395	  HARM_SEQ.forEach(([f,b]) => {
396	    schedNote(f, ht, b*BEAT*0.80, 'sine',     0.07, _bgmGain);
